function b64Encode(str){return btoa(unescape(encodeURIComponent(str)));}function b64Decode(str){return decodeURIComponent(escape(atob(str)));}function urlEncode(str){return encodeURIComponent(str);}function urlDecode(str){return decodeURIComponent(str.replace(/\+/g, " "));}function htmlEntityEncode(str){return [...str].map((ch) =>{switch (ch){case "&": return "&amp;";case "<": return "&lt;";case ">": return "&gt;";case '"': return "&quot;";case "'": return "&#39;";default:{const cp = ch.codePointAt(0);return cp > 127 ? `&#${cp};` : ch;}}}).join("");}function htmlEntityDecode(str){const doc = new DOMParser().parseFromString(str, "text/html");return doc.documentElement.textContent;}function rot13(s){return s.replace(/[a-zA-Z]/g, (c) =>{const base = c <= "Z" ? 65 : 97;return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);});}function toHex(s){return [...new TextEncoder().encode(s)].map((b) => b.toString(16).padStart(2, "0")).join("");}function fromHex(s){const clean = s.replace(/\s+/g, "");const bytes = [];for (let i = 0;i < clean.length;i += 2) bytes.push(parseInt(clean.substr(i, 2), 16));return new TextDecoder().decode(new Uint8Array(bytes));}function xorWithKey(s, key){if (!key) return s;const bytes = new TextEncoder().encode(s);const keyBytes = new TextEncoder().encode(key);const out = bytes.map((b, i) => b ^ keyBytes[i % keyBytes.length]);return [...out].map((b) => b.toString(16).padStart(2, "0")).join("");}async function sha256Hex(s){const enc = new TextEncoder().encode(s);const buf = await crypto.subtle.digest("SHA-256", enc);return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");}const RECIPE_OPERATIONS ={b64enc:{label: "To Base64", fn: b64Encode}, b64dec:{label: "From Base64", fn: b64Decode}, urlenc:{label: "URL Encode", fn: urlEncode}, urldec:{label: "URL Decode", fn: urlDecode}, htmlenc:{label: "HTML Entity Encode", fn: htmlEntityEncode}, htmldec:{label: "HTML Entity Decode", fn: htmlEntityDecode}, upper:{label: "To Uppercase", fn: (s) => s.toUpperCase()}, lower:{label: "To Lowercase", fn: (s) => s.toLowerCase()}, reverse:{label: "Reverse", fn: (s) => [...s].reverse().join("")}, rot13:{label: "ROT13", fn: rot13}, hexenc:{label: "To Hex", fn: toHex}, hexdec:{label: "From Hex", fn: fromHex}, xor:{label: "XOR (with key)", fn: xorWithKey, needsParam: true, paramLabel: "key"}, sha256:{label: "SHA-256 Hash", fn: sha256Hex, async: true},};let recipeSteps = []; let recipeStepCounter = 0;function addRecipeStep(){const select = document.getElementById("recipe-op-picker");const opKey = select.value;recipeStepCounter++;recipeSteps.push({id: recipeStepCounter, opKey, param: ""});renderRecipeSteps();executeRecipeChain();}function removeRecipeStep(id){recipeSteps = recipeSteps.filter((s) => s.id !== id);renderRecipeSteps();executeRecipeChain();}function moveRecipeStep(id, direction){const i = recipeSteps.findIndex((s) => s.id === id);const j = i + direction;if (i < 0 || j < 0 || j >= recipeSteps.length) return;[recipeSteps[i], recipeSteps[j]] = [recipeSteps[j], recipeSteps[i]];renderRecipeSteps();executeRecipeChain();}function updateRecipeParam(id, value){const step = recipeSteps.find((s) => s.id === id);if (step) step.param = value;executeRecipeChain();}function renderRecipeSteps(){const container = document.getElementById("recipe-steps");if (recipeSteps.length === 0){container.innerHTML = '<p style="color:var(--phosphor-dim-text); font-size:0.85rem;">// no steps yet - pick an operation above and click ADD</p>';return;}container.innerHTML = recipeSteps.map((step, i) =>{const op = RECIPE_OPERATIONS[step.opKey];const paramField = op.needsParam ? `<input type="text" placeholder="${op.paramLabel}" value="${step.param}" oninput="updateRecipeParam(${step.id}, this.value)" style="max-width:120px; margin-left:0.5rem;">` : "";return `<div style="display:flex; align-items:center; gap:0.5rem; padding:0.4rem 0; border-bottom:1px dashed var(--phosphor-dim);">
      <span style="color:var(--phosphor-dim-text); min-width:1.5rem;">${i + 1}.</span>
      <span style="flex:1;">${op.label}</span>
      ${paramField}
      <button onclick="moveRecipeStep(${step.id}, -1)" ${i === 0 ? "disabled" : ""} title="move up">&#9650;</button>
      <button onclick="moveRecipeStep(${step.id}, 1)" ${i === recipeSteps.length - 1 ? "disabled" : ""} title="move down">&#9660;</button>
      <button onclick="removeRecipeStep(${step.id})" title="remove">&times;</button>
    </div>`;}).join("");}async function executeRecipeChain(){const raw = document.getElementById("recipe-input").value;const out = document.getElementById("recipe-result");if (!raw || recipeSteps.length === 0){out.textContent = "";GAMA.say("idle");return;}let value = raw;const trace = [];try{for (const step of recipeSteps){const op = RECIPE_OPERATIONS[step.opKey];value = op.needsParam ? await op.fn(value, step.param) : await op.fn(value);trace.push({label: op.label, value});}out.innerHTML = trace.map((t) => `<div style="margin-bottom:0.4rem;"><span style="color:var(--phosphor-dim)">${t.label}:</span><br><span style="word-break:break-all;">${t.value.replace(/</g, "&lt;")}</span></div>` ).join("");GAMA.say("success");}catch (e){out.textContent = `// chain broke at some step - ${e.message}`;GAMA.say("error");}}function copyRecipeOutput(){const rows = document.querySelectorAll("#recipe-result > div");if (rows.length === 0) return;const lastValue = rows[rows.length - 1].querySelector("span:last-child").textContent;navigator.clipboard.writeText(lastValue);GAMA.log("Copied final chain output");}document.addEventListener("DOMContentLoaded", () =>{const picker = document.getElementById("recipe-op-picker");if (picker){picker.innerHTML = Object.entries(RECIPE_OPERATIONS) .map(([key, op]) => `<option value="${key}">${op.label}</option>`) .join("");renderRecipeSteps();}});